package com.hyzen.pharmd

import android.graphics.*
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File

@RunWith(AndroidJUnit4::class)
class ScanPerspectiveTest {
    @Test fun skewedPageIsRectangularAndInputRemainsUnchanged() {
        val source = Bitmap.createBitmap(400,400,Bitmap.Config.ARGB_8888)
        source.eraseColor(Color.BLACK)
        val q = listOf(.2,.1,.85,.2,.8,.9,.1,.8)
        val path = Path().apply { moveTo(80f,40f);lineTo(340f,80f);lineTo(320f,360f);lineTo(40f,320f);close() }
        Canvas(source).drawPath(path, Paint().apply { color=Color.WHITE })
        val before = IntArray(160000);source.getPixels(before,0,400,0,0,400,400)
        val output = ScanPerspective.warp(source,q)
        try {
            assertTrue(output.width in 260..290);assertTrue(output.height in 280..300)
            // All four interior quadrants are document pixels, not the black table.
            for(x in listOf(.1,.9)) for(y in listOf(.1,.9)) {
                assertEquals(Color.WHITE,output.getPixel((x*output.width).toInt(),(y*output.height).toInt()))
            }
            val after=IntArray(160000);source.getPixels(after,0,400,0,0,400,400)
            assertArrayEquals(before,after)
        } finally { output.recycle();source.recycle() }
    }
    @Test fun crossedDegenerateAndNonFiniteCornersAreRejected() {
        for(q in listOf(listOf(.1,.1,.9,.9,.9,.1,.1,.9), List(8){.5}, listOf(Double.NaN,.1,.9,.1,.9,.9,.1,.9))) {
            try { ScanPerspective.validate(q);fail("Invalid quad accepted") } catch(_: IllegalArgumentException) {}
        }
    }
    @Test fun perspectiveDraftSurvivesRestartAndUndoRestoresOriginalGeometry() {
        val context=InstrumentationRegistry.getInstrumentation().targetContext
        val store=ScanDraftStore(context);store.clear()
        val input=File.createTempFile("quad_", ".png",context.cacheDir)
        val bitmap=Bitmap.createBitmap(400,500,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.BLUE)
        input.outputStream().use { bitmap.compress(Bitmap.CompressFormat.PNG,100,it) };bitmap.recycle()
        try {
            val page=store.add(listOf(input.path))[0]
            val raw=File(store.originalInfo(page).getValue("path"));val before=raw.readBytes()
            val edited=store.edit(listOf(page),"gray",null,listOf(.2,.1,.9,.2,.8,.9,.1,.8))[0]
            val recreated=ScanDraftStore(context);assertEquals(listOf(edited),recreated.recover())
            val undone=recreated.undo(edited)[0]
            val image=BitmapFactory.decodeFile(undone)
            try { assertEquals(400,image.width);assertEquals(500,image.height);assertTrue(Color.blue(image.getPixel(20,20))>220) }
            finally { image.recycle() }
            assertArrayEquals(before,raw.readBytes())
        } finally { input.delete();store.clear() }
    }
    @Test fun exportRebuildsFromOriginalAndNeverClearsDraft() {
        val context=InstrumentationRegistry.getInstrumentation().targetContext
        val store=ScanDraftStore(context);store.clear()
        val input=File.createTempFile("export_original_", ".png",context.cacheDir)
        val bitmap=Bitmap.createBitmap(2400,2400,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.BLUE)
        input.outputStream().use { bitmap.compress(Bitmap.CompressFormat.PNG,100,it) };bitmap.recycle()
        val outputs=mutableListOf<File>()
        try {
            val pages=store.add(listOf(input.path))
            val raw=File(store.originalInfo(pages[0]).getValue("path"));val bytes=raw.readBytes()
            for(high in listOf(false,true)) {
                val pdf=File(store.exportPdf(pages,high));outputs.add(pdf)
                com.tom_roush.pdfbox.pdmodel.PDDocument.load(pdf).use { doc ->
                    assertEquals(1,doc.numberOfPages)
                    val resources=doc.getPage(0).resources
                    val image=resources.getXObject(resources.xObjectNames.first()) as com.tom_roush.pdfbox.pdmodel.graphics.image.PDImageXObject
                    assertEquals(if(high) 2400 else 1200,image.width)
                }
                assertEquals(pages,ScanDraftStore(context).recover())
                assertArrayEquals(bytes,raw.readBytes())
            }
            try { store.exportPdf(listOf("/missing.jpg"),true);fail("Invalid draft accepted") }
            catch(_:IllegalArgumentException) {}
            assertEquals(pages,store.pages())
        } finally { outputs.forEach{it.delete()};input.delete();store.clear() }
    }

