test/scan_corners_test.dart:
import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hyzen_pharmd/features/pdf_studio/presentation/scan_page_editor.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  testWidgets('four corners adjust independently and return normalized geometry at 320px', (tester) async {
    tester.view.physicalSize = const Size(320, 900);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    const channel = MethodChannel('com.hyzen.pharmd/camera_pages');
    final messenger = TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger;
    messenger.setMockMethodCallHandler(channel, (_) async => {
      'bytes': base64Decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGNgqC/7DwADbQH1vXeWcAAAAABJRU5ErkJggg=='),
      'filter': 'original',
    });
    addTearDown(() => messenger.setMockMethodCallHandler(channel, null));
    ScanPageEdit? result;
    await tester.pumpWidget(MaterialApp(home: Builder(builder: (context) => Scaffold(body: TextButton(
      onPressed: () async { result = await Navigator.of(context).push<ScanPageEdit>(MaterialPageRoute(builder: (_) => const ScanPageEditor(path: '/draft/page.jpg', nativeDraft: true))); },
      child: const Text('Edit'),
    )))));
    await tester.runAsync(() async {
      await tester.tap(find.text('Edit'));
      await tester.pump();
      for (var i = 0; i < 100; i++) {
        await Future<void>.delayed(const Duration(milliseconds: 10));
        await tester.pump();
        if (find.byType(CircularProgressIndicator).evaluate().isEmpty) break;
      }
    });
    await tester.pumpAndSettle();
    await tester.tap(find.text('4-corner crop'));
    await tester.pumpAndSettle();
    await tester.drag(find.byKey(const ValueKey('crop-corner-0')), const Offset(25, 15));
    await tester.pump();
    await tester.runAsync(() async {
      await tester.tap(find.text('Apply'));
      await tester.pump();
      await Future<void>.delayed(const Duration(milliseconds: 20));
    });
    await tester.pumpAndSettle();
    expect(result?.crop, hasLength(8));
    expect(result!.crop![0], greaterThan(.03));
    expect(result!.crop![2], .97);
    expect(result!.crop![3], .03);
    expect(tester.takeException(), isNull);
  });
}
